package com.tomessa.miff.domain.miff

import java.security.SecureRandom

/*
 * SECURITY, for this file: a join code is a secret (whoever holds it can enter the Miff). It is generated by the phone with
 * a cryptographic generator, never logged, never put in an analytics event, a crash report or an exception message.
 */

/**
 * The secret code of a Miff (ticket Miff 5.3, backend/data-model.md section 2.4): 12 characters out of 31 symbols (no I, L,
 * O, 0, 1: they are mistaken for each other), about 59 bits. Same alphabet and same length as the rules of Firestore.
 */
object JoinCode {
    const val ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789"
    const val LENGTH = 12
    const val GROUP_SIZE = 4

    /** Same shape as the rule `isJoinCode`. */
    val SHAPE = Regex("^[A-HJ-KM-NP-Z2-9]{12}$")

    fun isValid(code: String): Boolean = SHAPE.matches(code)

    /**
     * A new code. Rejection sampling: a random byte is only used when it falls in the largest multiple of 31 that fits in
     * 256 (248), so that no symbol is more likely than another (no modulo bias).
     */
    fun generate(random: SecureRandom = SecureRandom()): String {
        val limit = 256 - 256 % ALPHABET.length
        val out = StringBuilder(LENGTH)
        val buffer = ByteArray(LENGTH * 2)
        while (out.length < LENGTH) {
            random.nextBytes(buffer)
            for (b in buffer) {
                val value = b.toInt() and 0xFF
                if (value < limit && out.length < LENGTH) out.append(ALPHABET[value % ALPHABET.length])
            }
        }
        return out.toString()
    }

    /**
     * What was typed or pasted, cleaned: capitals, and spaces, tabs, dashes and non-breaking spaces removed (a code is read
     * aloud or copied from a message as "XTZR SP36 7988" or "XTZR-SP36-7988"). Nothing else is changed: a letter that is not
     * in the alphabet stays, so that the person is told about it ([analyze]).
     */
    fun normalize(raw: String): String {
        val out = StringBuilder(raw.length)
        for (c in raw) {
            if (c.isWhitespace() || c == NO_BREAK_SPACE || c in DASHES) continue
            out.append(c.uppercaseChar())
        }
        return out.toString()
    }

    private val NO_BREAK_SPACE = 0x00A0.toChar()

    /** Hyphen, non-breaking hyphen, figure dash, en dash, em dash, minus sign, underscore: what a code is copied with. */
    private val DASHES: Set<Char> =
        setOf('-', '_') + listOf(0x2010, 0x2011, 0x2012, 0x2013, 0x2014, 0x2212).map { it.toChar() }

    /** What the screen needs to know about the text in the field (no network, ticket criterion J2). */
    fun analyze(raw: String): CodeInput {
        val cleaned = normalize(raw)
        // The field keeps the first 12 characters: what is typed beyond is not kept (a longer pasted text is cut, and the
        // person sees the 12 that were kept). Only what is kept is judged.
        val kept = cleaned.take(LENGTH)
        val hasForeign = kept.any { ALPHABET.indexOf(it) < 0 }
        return CodeInput(
            code = kept,
            hasForeignCharacter = hasForeign,
            isComplete =
                kept.length == LENGTH && !hasForeign,
        )
    }

    /** "XTZRSP367988" -> "XTZR SP36 7988" (display and sharing). */
    fun grouped(code: String): String = code.chunked(GROUP_SIZE).joinToString(" ")

    /** Read aloud by groups of 4, letter by letter: "X T Z R, S P 3 6, 7 9 8 8". */
    fun spoken(code: String): String = code.chunked(GROUP_SIZE).joinToString(", ") { it.toList().joinToString(" ") }
}

/** The state of the code field. [code] is at most 12 characters, normalized. */
data class CodeInput(
    val code: String,
    val hasForeignCharacter: Boolean,
    val isComplete: Boolean,
) {
    override fun toString(): String = "CodeInput(redacted)"
}
